E["quest:96395"] = {t="quest",n="An Ancient Grudge",z="hallofthanes",s="Within the Hall of Thanes, Faldrim Anvilmar's spirit remains troubled by an old grievance. His ghostly attendant asks travelers to bring him peace.",h="Within the Hall of Thanes, Faldrim Anvilmar's spirit remains troubled by an old grievance.",sec={{t="A Plea From the Grave",b="A ghostly attendant remains in the Hall of Thanes, where Faldrim Anvilmar once ruled. The spirit can barely speak across the veil between the living and the dead. It asks you to quiet its master's restless spirit. It seeks peace for him, not freedom for itself.",sp=0},{t="The Weight of the Past",b="Faldrim Anvilmar remains bound to the physical world by an ancient grudge. His ghost is agitated and hostile. He cannot rest until someone grants him a forceful release.",sp=1}},faq={{q="Who is Faldrim Anvilmar?",a="Faldrim Anvilmar was a dwarven thane whose restless ghost haunts the Hall of Thanes. His Ghostly Attendant says an ancient grudge consumes him and keeps him from rest.",al={"faldrim anvilmar lore","who is faldrim","thane anvilmar"}},{q="Where is the Hall of Thanes located?",a="The Hall of Thanes lies in caverns beneath Old Ironforge, inside the dwarven capital of Ironforge.",al={"hall of thanes location","where is hall of thanes","hall of thanes entrance"}},{q="Why is the ghost of Faldrim Anvilmar hostile?",a="Faldrim Anvilmar's ghost is hostile because an ancient grudge consumes him. The Ghostly Attendant says this grievance keeps the former thane from rest.",al={"why is faldrim angry","why is thane attacking","ancient grudge explanation"}},{q="Who gives the quest An Ancient Grudge?",a="A Ghostly Attendant inside the Hall of Thanes asks you to bring peace to its former master.",al={"who starts ancient grudge","ghostly attendant quest","quest giver"}},{q="What must you do to complete the quest?",a="You confront Faldrim Anvilmar's ghost in the Hall of Thanes and defeat him in combat to release him from torment. Then you report back to the Ghostly Attendant.",al={"how to finish ancient grudge","put faldrim to rest","ancient grudge objective"}},{q="Is Faldrim related to the town of Anvilmar?",a="No one knows whether Faldrim Anvilmar is related to the town of Anvilmar in Coldridge Valley. They share a name, but his family and any tie to the town are unknown.",al={"is faldrim from anvilmar","anvilmar coldridge connection","anvilmar family"}}},ang={["race:Dwarf"]="As a dwarf, you see a sobering reminder that an ancient grudge can outlast death itself.",["class:Priest"]="As a priest, you know that lingering grudges and unatoned sorrow can bind a spirit to the physical world long after the body is dust.",["class:Paladin"]="As a paladin, you take on the solemn duty of bringing peace to the suffering dead."},kw={"ancient grudge","anvilmar","dwarf ghost","faldrim anvilmar","ghostly attendant","hall of thanes","restless spirit","thane"},rel={"zone:hallofthanes","subzone:anvilmar"},m={level="15",id=96395},src={"In-game quest text: An Ancient Grudge"},fv=true}
E["zone:hallofthanes"] = {t="dungeon",n="Hall of Thanes",z="hallofthanes",s="Alliance defenders now seek a way into the Hall of Thanes, deep beneath Ironforge. Its old vaults hold dwarven relics, and danger has reached those depths.",h="Alliance defenders now seek a way into the Hall of Thanes, deep beneath Ironforge.",sec={{t="Secrets Beneath the Mountain",b="Hammers ring in Ironforge's Great Forge, but forgotten halls run deeper beneath the stone. The Hall of Thanes lies in those ancient reaches, tied to dwarven bloodlines and relics of stonecraft. Now Alliance champions must enter its shadowed vaults and guard the depths.",sp=0},{t="Uncovering the Path",b="The route into the Hall of Thanes is hidden from Ironforge's everyday travelers. Its corridors have been sealed or concealed. To find a way through, recover an Underground Map and use forgotten charts to navigate the deeper tunnels to the entrance.",sp=0},{t="The Threat of Dirgehammer",b="Durgen Dirgehammer commands the inner sanctuary of the Hall of Thanes. Plunder, an enchanted guardian, and the fiery brute Magmatus threaten its halls. Faldrim Anvilmar comes from an ancient dwarven lineage. Defeating Durgen ends the unrest beneath the city and protects the sacred halls from subversion.",sp=1,bt={"q96392.4"}}},faq={{q="Where is the Hall of Thanes located?",a="The Hall of Thanes lies beneath Ironforge, in the mountain's deeper, restricted passages, away from the main city thoroughfares.",al={"hall of thanes location","where is hall of thanes","ironforge dungeon location"},it="place",gp=true},{q="How do I gain access to the Hall of Thanes?",a="Earthseer Farsen watches Gol'Bolar Quarry in Dun Morogh and begins the route. Recover the Underground Map, then follow Old Ironforge Incursion into the Hall of Thanes.",al={"how to get into hall of thanes","hall of thanes attunement","underground map quest"},it="purpose",gp=true},{q="What bosses are inside the Hall of Thanes?",a="Four major threats await inside: Faldrim Anvilmar, Magmatus, the enchanted golem Plunder, and Durgen Dirgehammer.",al={"boss list","who are the bosses","hall of thanes bosses"},it="threat",gp=true},{q="What level range is recommended for this dungeon?",a="The Hall of Thanes is built for Alliance adventurers between levels 13 and 18, an early challenge deep beneath Ironforge.",al={"what level is hall of thanes","hall of thanes level range"},it="purpose",gp=true},{q="Can Horde players enter the Hall of Thanes?",a="No. The Hall of Thanes is for the Alliance and lies beneath their capital, Ironforge.",al={"can horde do hall of thanes","is hall of thanes alliance only"},it="side",gp=true},{q="What does defeating Durgen Dirgehammer achieve?",a="Defeating Durgen Dirgehammer breaks the hold of rogue dwarven forces and their summoned constructs beneath Ironforge. The ancestral vaults below the Great Forge are safe again.",al={"why kill dirgehammer","final boss story","durgen dirgehammer lore"},sp=1,it="next_step",gp=true,bt={"q96392.4"}},{q="What is the Hall of Thanes?",a="The Hall of Thanes is an instanced dungeon deep beneath the dwarf capital of Ironforge. While Ironforge usually bustles as the grand home of the Bronzebeard clan, this subterranean domain harbors brewing internal threats and hostile encounters, requiring seasoned defenders of the Alliance to delve beneath the mountain and restore order.",al={"hall of thanes lore","what is this dungeon","hall of thanes dungeon"},it="place",add="89d0670c"},{q="How did I end up in the Hall of Thanes?",a="You followed the trail of an ancient subterranean map uncovered deep within dwarven territory. After unraveling its secrets and gaining access from within Ironforge, your search led you into these forgotten stone halls carved directly under the mountain.",al={"how did i get here","how did i end up here","how did i find the hall of thanes"},it="arrival",add="20f1c0f0"},{q="What am I supposed to be doing in the Hall of Thanes?",a="You are here to venture deep into these ancestral vaults, overcome the hostile forces holding them, and strike down the threats lurking in the dark. Your expedition culminates in confronting dangerous renegades and guardians, including Faldrim Anvilmar, Plunder, Magmatus, and Durgen Dirgehammer.",al={"what am i doing here","why am i here","what is my goal here"},it="purpose",add="b863ae36"}},ang={["race:Dwarf"]="As a dwarf, you enter Dun Morogh's ancestral bedrock and drive defilers from sacred halls bearing legendary clan names.",["faction:Alliance"]="As an Alliance member, you help protect Ironforge's stability by clearing deep caverns and securing the High Seat.",["race:Gnome"]="As a gnome living alongside your close allies in Ironforge, you have reason to help stop mechanical constructs like Plunder from threatening your shared refuge."},kw={"attunement","dungeon","durgen dirgehammer","faldrim anvilmar","hall of thanes","ironforge","magmatus","plunder","underground map"},rel={"zone:ironforge","quest:96391","subzone:anvilmar","topic:alliance"},m={levels="13-18"},src={"Hall of Thanes (instance)"}}
